def test_phase4_field_extra_placed_can_switch_owner_energy_active() -> None:
    engine = RulesEngine(
        effect_rules={
            424284: [
                {
                    "trigger": "owner_field_extra_placed",
                    "handler_id": "auto_switch_up_to_n_owner_energy_active_on_field_extra_placed",
                    "handler_params": {"max_targets": 2, "allowed_colors": "yellow"},
                }
            ]
        },
    )
    state = engine.initialize_game(
        p1_leader_card_id=1,
        p1_deck_card_ids=_deck(1000),
        p2_leader_card_id=2,
        p2_deck_card_ids=_deck(2000),
        shuffle_decks=False,
    )
    state = _to_main(engine, state)
    state.players[1].battle_area.append(
        CardInstance(instance_id=880357, card_id=424284, owner_id=1, card_type="BATTLE", energy_cost=0)
    )
    engine._register_card_effects(state, player_id=1, source_zone="battle", card=state.players[1].battle_area[0])
    state.players[1].energy = [
        CardInstance(instance_id=880358, card_id=900961, owner_id=1, color="Yellow", resting=True),
        CardInstance(instance_id=880359, card_id=900962, owner_id=1, color="Yellow", resting=True),
        CardInstance(instance_id=880360, card_id=900963, owner_id=1, color="Blue", resting=True),
    ]
    state.players[1].hand = [
        CardInstance(
            instance_id=880361,
            card_id=900964,
            owner_id=1,
            card_type="EXTRA",
            energy_cost=0,
            keywords=("Field",),
            has_counter=False,
        )
    ]
    play_extra = next(a for a in engine.get_legal_actions(state, 1) if a.action_type == ActionType.PLAY_CARD_FROM_HAND and a.hand_index == 0)
    state = engine.apply_action(state, play_extra)
    state = engine.apply_action(state, Action(action_type=ActionType.PASS_COUNTER_WINDOW, player_id=2))
    assert state.players[1].energy[0].resting is False
    assert state.players[1].energy[1].resting is False
    assert state.players[1].energy[2].resting is True
    assert any(evt.name == "field_extra_placed" for evt in state.effect_events)
    assert any(cp.name == "effect_auto_switch_up_to_n_owner_energy_active_on_field_extra_placed" for cp in state.checkpoints)


def test_phase4_power_ball_field_extra_placed_can_add_matching_card_from_deck_to_hand() -> None:
    card_id = 995320
    deck_match_id = 995321
    deck_filler_id = 995322
    skill_text = (
        "[Field] (Place and activate this card in your Battle Area. It remains in your Battle Area until you activate another [Field]. "
        "When you do, place this card in its owner's Drop Area.)<br>"
        "[Auto] When this card is placed in a Battle Area, choose up to 1 green ≪Great Ape≫ card from your deck, add it to your hand, then shuffle your deck.<br>"
        "[Activate: Main] Switch this card to Rest Mode: Choose up to 1 red or green ≪Saiyan≫ card in your Battle Area, and it gets +5000 power for the duration of the turn."
    )
    engine = RulesEngine(
        effect_rules={
            card_id: extract_effect_rules_from_card(
                SimpleNamespace(card_skill_unstyled=skill_text, card_type="EXTRA")
            )
        }
    )
    engine._card_cache[(deck_match_id, "front")] = CardRuntimeData(
        card_name="Great Ape Target",
        card_type="BATTLE",
        color="Green",
        traits=("Great Ape",),
    )
    engine._card_cache[(deck_filler_id, "front")] = CardRuntimeData(
        card_name="Filler",
        card_type="BATTLE",
        color="Red",
        traits=("Saiyan",),
    )
    state = engine.initialize_game(
        p1_leader_card_id=1,
        p1_deck_card_ids=_deck(10000),
        p2_leader_card_id=2,
        p2_deck_card_ids=_deck(11000),
        first_player=1,
        shuffle_decks=False,
    )
    field_extra = CardInstance(
        instance_id=995323,
        card_id=card_id,
        owner_id=1,
        card_type="EXTRA",
        keywords=("Field",),
        has_auto=True,
        skill_text_raw=skill_text,
    )
    state.players[1].battle_area = [field_extra]
    state.players[1].deck = [deck_filler_id, deck_match_id]
    deck_count_before = len(state.players[1].deck)
    hand_count_before = len(state.players[1].hand)
